class RangeSet:
    """A normalized set of half-open integer ranges [start, end)."""

    def __init__(self, ranges=()):
        self._ranges = self._normalize(self._validated(ranges))

    # ------------------------------------------------------------------ #
    # validation helpers
    # ------------------------------------------------------------------ #
    @staticmethod
    def _check_int(value, name):
        if type(value) is not int:
            raise TypeError("%s must be int, got %s" % (name, type(value).__name__))

    @classmethod
    def _check_pair(cls, start, end):
        cls._check_int(start, "start")
        cls._check_int(end, "end")
        if start > end:
            raise ValueError("start must be <= end, got (%d, %d)" % (start, end))

    @classmethod
    def _validated(cls, pairs):
        result = []
        for pair in pairs:
            start, end = pair
            cls._check_pair(start, end)
            if start < end:
                result.append((start, end))
        return result

    # ------------------------------------------------------------------ #
    # normalization helpers
    # ------------------------------------------------------------------ #
    @staticmethod
    def _merge(intervals):
        merged = []
        for start, end in sorted(intervals):
            if merged and start <= merged[-1][1]:
                prev_start, prev_end = merged[-1]
                merged[-1] = (prev_start, max(prev_end, end))
            else:
                merged.append((start, end))
        return merged

    def _normalize(self, intervals):
        return self._merge(intervals)

    # ------------------------------------------------------------------ #
    # public API
    # ------------------------------------------------------------------ #
    def ranges(self):
        return [tuple(r) for r in self._ranges]

    def add(self, start, end):
        self._check_pair(start, end)
        if start < end:
            self._ranges = self._normalize(self._ranges + [(start, end)])

    def remove(self, start, end):
        self._check_pair(start, end)
        if start < end:
            remaining = []
            for a, b in self._ranges:
                if b <= start or a >= end:
                    remaining.append((a, b))
                else:
                    if a < start:
                        remaining.append((a, start))
                    if end < b:
                        remaining.append((end, b))
            self._ranges = self._normalize(remaining)

    def contains(self, point):
        self._check_int(point, "point")
        return any(a <= point < b for a, b in self._ranges)

    def clip(self, start, end):
        self._check_pair(start, end)
        if start >= end:
            return []
        clipped = []
        for a, b in self._ranges:
            lo, hi = max(a, start), min(b, end)
            if lo < hi:
                clipped.append((lo, hi))
        return self._merge(clipped)

